// Nodo "Configuración" — EDITÁ ESTOS VALORES.
const DESTINATARIO = 'tu.mail@pepsico.com';           // a quién le llega el resumen (podés poner varios separados por coma)
const LINK_DASHBOARD = '';                              // pegá acá el link del dashboard cuando lo publiques
const UMBRAL_VARIACION_PCT = 1;                         // cambios de precio menores a este % no se reportan

const fecha = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Argentina/Buenos_Aires' }).format(new Date());
return [{ json: { fecha, destinatario: DESTINATARIO, link_dashboard: LINK_DASHBOARD, umbral: UMBRAL_VARIACION_PCT } }];

// Nodo "Resumen semanal" — agrega por marca y por cadena y arma el pedido a Claude.
const filas = $input.all().map((i) => i.json);
const prom = (a) => (a.length ? a.reduce((s, x) => s + x, 0) / a.length : null);
const r1 = (n) => (n == null ? null : Math.round(n * 10) / 10);

function agrupar(clave) {
  const g = {};
  for (const f of filas) {
    const k = f[clave] || 'Sin dato';
    g[k] = g[k] || { skus: 0, vars: [], promo: 0, sinStock: 0 };
    g[k].skus++;
    if (f.var_7d_pct != null) g[k].vars.push(Number(f.var_7d_pct));
    if (f.en_promo) g[k].promo++;
    if (!f.disponible) g[k].sinStock++;
  }
  return Object.entries(g).map(([k, v]) => ({
    [clave]: k, skus: v.skus, var_prom_7d: r1(prom(v.vars)),
    pct_promo: r1((100 * v.promo) / v.skus), sin_stock: v.sinStock,
  }));
}

const conVar = filas.filter((f) => f.var_7d_pct != null).sort((a, b) => b.var_7d_pct - a.var_7d_pct);
const fmt = (f) => `${f.retailer} · ${f.producto} · $${f.precio_hace_7d} → $${f.precio_hoy} (${f.var_7d_pct}%)`;

const datos = `Semana cerrada al ${$('Configuración').first().json.fecha}.
Por marca: ${JSON.stringify(agrupar('marca'))}
Por cadena: ${JSON.stringify(agrupar('retailer'))}
Mayores subas 7d:\n${conVar.slice(0, 10).map(fmt).join('\n') || '(sin datos)'}
Mayores bajas 7d:\n${conVar.slice(-10).reverse().filter((f) => f.var_7d_pct < 0).map(fmt).join('\n') || '(sin datos)'}`;

return [{ json: {
  total: filas.length,
  body: {
    model: 'claude-sonnet-5-5',
    max_tokens: 1500,
    system: `Sos analista de pricing de PepsiCo Argentina (snacks) en supermercados online.
Escribí el resumen semanal en español rioplatense: 4 a 7 bullets con cifras concretas (marca, cadena, %), cerrando con 1 o 2 puntos a seguir la semana próxima.
Si "var_prom_7d" es null es porque todavía no hay una semana de historia: decilo y describí la foto actual.
No inventes datos ni causas. Devolvé SOLO HTML: un <ul> con <li>, podés usar <b>.`,
    messages: [{ role: 'user', content: datos }],
  },
} }];

// Nodo "Armar mail semanal"
const cfg = $('Configuración').first().json;
const total = $('Resumen semanal').first().json.total;
const ia = $input.first().json || {};
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

let analisis = (ia.content || []).filter((c) => c.type === 'text').map((c) => c.text).join('').trim();
analisis = analisis.replace(/```html?|```/g, '').replace(/<(?!\/?(ul|li|b|strong)\b)[^>]*>/gi, '');
if (!/<li/i.test(analisis)) analisis = analisis ? `<p>${esc(analisis)}</p>` : '<p>(El análisis automático no estuvo disponible; el detalle completo está en el Excel adjunto.)</p>';

const html = `<!doctype html><html><body style="margin:0;background:#f4f4f2">
<table width="100%" cellpadding="0" cellspacing="0" style="background:#f4f4f2;padding:24px 0"><tr><td align="center">
<table width="680" cellpadding="0" cellspacing="0" style="background:#fff;border-radius:10px;padding:28px;font-family:Segoe UI,Arial,sans-serif;color:#0b0b0b"><tr><td>
  <div style="font-size:12px;color:#52514e;text-transform:uppercase;letter-spacing:.06em">Monitor de precios · Snacks PepsiCo</div>
  <h1 style="margin:4px 0 12px;font-size:22px">Resumen semanal al ${esc(cfg.fecha)}</h1>
  <div style="font-size:14px;line-height:1.5">${analisis}</div>
  <p style="font-size:13px;color:#52514e;margin-top:20px">📎 Adjunto: Excel con los ${total} precios relevados (producto × cadena) y su variación contra hace 7 días.</p>
  ${cfg.link_dashboard ? `<p><a href="${esc(cfg.link_dashboard)}" style="background:#2a78d6;color:#fff;padding:10px 16px;border-radius:6px;text-decoration:none;font-weight:600">Abrir dashboard</a></p>` : ''}
</td></tr></table></td></tr></table></body></html>`;

return [{ json: { destinatario: cfg.destinatario, asunto: `Resumen semanal de precios snacks — ${cfg.fecha}`, html } }];
